package com.ebuddy.config;
import org.springframework.context.annotation.Configuration; import org.springframework.messaging.simp.config.MessageBrokerRegistry; import org.springframework.web.socket.config.annotation.*;
@Configuration @EnableWebSocketMessageBroker public class WebSocketConfig implements WebSocketMessageBrokerConfigurer { public void configureMessageBroker(MessageBrokerRegistry r){r.enableSimpleBroker("/queue","/topic");r.setApplicationDestinationPrefixes("/app");r.setUserDestinationPrefix("/user");} public void registerStompEndpoints(StompEndpointRegistry r){r.addEndpoint("/v1/ws","/ws-chat").setAllowedOriginPatterns("*");} }
